"""GHARMATE database layer: PostgreSQL/Supabase in production, SQLite locally."""
import os, sqlite3
from pathlib import Path
from contextlib import contextmanager
BASE_DIR = Path(__file__).resolve().parent
SQLITE_PATH = BASE_DIR / "homemate.db"
DATABASE_URL = os.environ.get("DATABASE_URL", "").strip()
USE_POSTGRES = bool(DATABASE_URL)

class DatabaseAdapter:
    def __init__(self, connection, postgres=False): self.connection, self.postgres = connection, postgres
    def execute(self, query, params=()):
        if self.postgres: query = query.replace("?", "%s")
        return self.connection.execute(query, params)
    def executescript(self, script):
        if self.postgres: raise RuntimeError("SQLite script used with PostgreSQL")
        return self.connection.executescript(script)

SQLITE_SCHEMA = """
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member',language TEXT NOT NULL DEFAULT 'en');
CREATE TABLE IF NOT EXISTS timetable(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,activity_time TEXT NOT NULL,days TEXT,notes TEXT,created_by INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS chores(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,assigned_to INTEGER REFERENCES users(id),due_date TEXT,notes TEXT,done INTEGER DEFAULT 0,created_by INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,event_date TEXT NOT NULL,event_time TEXT,details TEXT,created_by INTEGER NOT NULL REFERENCES users(id),event_type TEXT NOT NULL DEFAULT 'general',person_id INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS prayer_times(prayer_name TEXT PRIMARY KEY,prayer_time TEXT NOT NULL,updated_by INTEGER REFERENCES users(id));
CREATE TABLE IF NOT EXISTS announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,message TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chore_rotation_rules(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,member_ids TEXT NOT NULL,frequency TEXT NOT NULL,next_due_date TEXT,last_assigned_to INTEGER,active INTEGER DEFAULT 1,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS polls(id INTEGER PRIMARY KEY AUTOINCREMENT,question TEXT NOT NULL,description TEXT,closes_at TEXT,is_closed INTEGER DEFAULT 0,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS poll_options(id INTEGER PRIMARY KEY AUTOINCREMENT,poll_id INTEGER NOT NULL REFERENCES polls(id) ON DELETE CASCADE,option_text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS poll_votes(id INTEGER PRIMARY KEY AUTOINCREMENT,poll_id INTEGER NOT NULL REFERENCES polls(id) ON DELETE CASCADE,option_id INTEGER NOT NULL REFERENCES poll_options(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(poll_id,user_id));
CREATE TABLE IF NOT EXISTS outings(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),destination TEXT NOT NULL,purpose TEXT,departure_at TEXT NOT NULL,expected_return_at TEXT,actual_return_at TEXT,status TEXT DEFAULT 'away',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS emergency_contacts(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,contact_name TEXT,phone TEXT,address TEXT,instructions TEXT,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS visitors(id INTEGER PRIMARY KEY AUTOINCREMENT,visitor_name TEXT NOT NULL,phone TEXT,purpose TEXT,host_id INTEGER REFERENCES users(id),expected_at TEXT,arrived_at TEXT,departed_at TEXT,notes TEXT,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
"""
POSTGRES_SCHEMA = [
"CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member',language TEXT NOT NULL DEFAULT 'en')",
"CREATE TABLE IF NOT EXISTS timetable(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,activity_time TEXT NOT NULL,days TEXT,notes TEXT,created_by BIGINT NOT NULL REFERENCES users(id))",
"CREATE TABLE IF NOT EXISTS chores(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,assigned_to BIGINT REFERENCES users(id),due_date TEXT,notes TEXT,done INTEGER DEFAULT 0,created_by BIGINT NOT NULL REFERENCES users(id))",
"CREATE TABLE IF NOT EXISTS events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,event_date TEXT NOT NULL,event_time TEXT,details TEXT,created_by BIGINT NOT NULL REFERENCES users(id),event_type TEXT NOT NULL DEFAULT 'general',person_id BIGINT REFERENCES users(id))",
"CREATE TABLE IF NOT EXISTS prayer_times(prayer_name TEXT PRIMARY KEY,prayer_time TEXT NOT NULL,updated_by BIGINT REFERENCES users(id))",
"CREATE TABLE IF NOT EXISTS announcements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,message TEXT NOT NULL,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)",
"CREATE TABLE IF NOT EXISTS chore_rotation_rules(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,member_ids TEXT NOT NULL,frequency TEXT NOT NULL,next_due_date TEXT,last_assigned_to BIGINT,active INTEGER DEFAULT 1,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)",
"CREATE TABLE IF NOT EXISTS polls(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,question TEXT NOT NULL,description TEXT,closes_at TEXT,is_closed INTEGER DEFAULT 0,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)",
"CREATE TABLE IF NOT EXISTS poll_options(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,poll_id BIGINT NOT NULL REFERENCES polls(id) ON DELETE CASCADE,option_text TEXT NOT NULL)",
"CREATE TABLE IF NOT EXISTS poll_votes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,poll_id BIGINT NOT NULL REFERENCES polls(id) ON DELETE CASCADE,option_id BIGINT NOT NULL REFERENCES poll_options(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(poll_id,user_id))",
"CREATE TABLE IF NOT EXISTS outings(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),destination TEXT NOT NULL,purpose TEXT,departure_at TEXT NOT NULL,expected_return_at TEXT,actual_return_at TEXT,status TEXT DEFAULT 'away',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)",
"CREATE TABLE IF NOT EXISTS emergency_contacts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title TEXT NOT NULL,contact_name TEXT,phone TEXT,address TEXT,instructions TEXT,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)",
"CREATE TABLE IF NOT EXISTS visitors(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,visitor_name TEXT NOT NULL,phone TEXT,purpose TEXT,host_id BIGINT REFERENCES users(id),expected_at TEXT,arrived_at TEXT,departed_at TEXT,notes TEXT,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)"
]
@contextmanager
def get_db():
    if USE_POSTGRES:
        import psycopg
        from psycopg.rows import dict_row
        conn=psycopg.connect(DATABASE_URL,row_factory=dict_row,prepare_threshold=None)
    else:
        conn=sqlite3.connect(SQLITE_PATH); conn.row_factory=sqlite3.Row; conn.execute("PRAGMA foreign_keys=ON")
    db=DatabaseAdapter(conn,USE_POSTGRES)
    try:
        yield db; conn.commit()
    except Exception:
        conn.rollback(); raise
    finally: conn.close()
def init_db():
    with get_db() as db:
        if USE_POSTGRES:
            for sql in POSTGRES_SCHEMA: db.execute(sql)
            db.execute("ALTER TABLE events ADD COLUMN IF NOT EXISTS event_type TEXT NOT NULL DEFAULT 'general'")
            db.execute("ALTER TABLE events ADD COLUMN IF NOT EXISTS person_id BIGINT REFERENCES users(id)")
        else:
            db.executescript(SQLITE_SCHEMA)
            cols={r['name'] for r in db.execute("PRAGMA table_info(events)").fetchall()}
            if 'event_type' not in cols: db.execute("ALTER TABLE events ADD COLUMN event_type TEXT NOT NULL DEFAULT 'general'")
            if 'person_id' not in cols: db.execute("ALTER TABLE events ADD COLUMN person_id INTEGER REFERENCES users(id)")
